SEPARATORS = ["\n\n", "\n", ". ", " "]  # coarse -> fine

def recursive_split(text, size, seps=SEPARATORS):
    if len(text) <= size or not seps:
        return [text]
    sep, rest = seps[0], seps[1:]
    pieces, out, buf = text.split(sep), [], ""
    for p in pieces:
        if len(buf) + len(p) <= size:
            buf += p + sep
        else:
            out += recursive_split(buf, size, rest) if buf else []
            buf = p + sep
    if buf:
        out += recursive_split(buf, size, rest)
    return [c for c in out if c.strip()]

def to_records(chunks, source, doc_title):
    records = []
    for i, text in enumerate(chunks):
        records.append({
            "id": f"{source}::chunk-{i}",   # stable, unique id
            "text": text,
            "metadata": {
                "source": source,
                "title": doc_title,
                "chunk_index": i,
            },
        })
    return records
# records[0]['metadata'] later powers filtering + citations

