SEPARATORS = ["\n\n", "\n", ". ", " "]

def recursive_split(text, size, seps=SEPARATORS):
    text = text.strip()
    if len(text) <= size or not seps:
        return [text] if text else []
    sep, rest = seps[0], seps[1:]
    out, buf = [], ""
    for piece in text.split(sep):
        candidate = f"{buf}{sep}{piece}" if buf else piece
        if len(candidate) <= size:
            buf = candidate
        else:
            out += recursive_split(buf, size, rest)
            buf = piece
    out += recursive_split(buf, size, rest)
    return [c for c in out if c.strip()]

def to_records(chunks, source):
    return [
        {"id": f"{source}::c{i}", "text": c,
         "metadata": {"source": source, "chunk_index": i}}
        for i, c in enumerate(chunks)
    ]

doc = "Intro paragraph here.\n\nRefund policy: 14 days. Prorated for enterprise."
chunks = recursive_split(doc, size=40)
records = to_records(chunks, source="policy.md")
for r in records:
    print(r["id"], "->", repr(r["text"]))

