def chunk(text, size=40, overlap=15):
    step = size - overlap            # advance less than size -> windows overlap
    out = []
    for i in range(0, len(text), step):
        piece = text[i:i + size]
        if piece.strip():
            out.append(piece)
    return out

doc = "Enterprise refunds are processed within 14 days per policy."
for c in chunk(doc, size=40, overlap=15):
    print(repr(c))
# now a window spanning 'refunds ... within 14 days' exists intact,
# so the full fact is embedded together and becomes retrievable

