def chunk_with_meta(text: str, source: str, size: int = 200, overlap: int = 40) -> list[dict]:
    if overlap >= size:
        raise ValueError("overlap must be smaller than size")
    step = size - overlap
    records, idx = [], 0
    for start in range(0, len(text), step):
        piece = text[start:start + size]
        if not piece.strip():
            continue
        records.append({
            "id": f"{source}::c{idx}",
            "text": piece,
            "metadata": {"source": source, "start": start},
        })
        idx += 1
    return records

if __name__ == "__main__":
    recs = chunk_with_meta("abcdefghij" * 3, source="doc.txt", size=12, overlap=4)
    for r in recs:
        print(r["id"], r["metadata"]["start"], repr(r["text"]))

